package dkls

import (
	"encoding/hex"
	"os"
	"path/filepath"
	"testing"

	libtss "github.com/0xCarbon/libtss/libtss-go/tss"
)

// Cross-version fixtures generated by the v4.1.0 tree (tag v4.1.0,
// 92362c6b) with its own RunDKGInProcess + KeyshareJSONFromHandle.
// Test-only keys. Proves F2's binding accepts genuine pre-B1 shares and
// that they still sign under the current code.

func xversionShare(t *testing.T, name string) string {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("..", "testdata", "xversion", name))
	if err != nil {
		t.Fatal(err)
	}
	return string(b)
}

func TestXVersion_OldShareSignsInNewCode(t *testing.T) {
	handle0, ks0, err := ImportKeyshare(xversionShare(t, "dkls-share-0.json"))
	if err != nil {
		t.Fatalf("import v4.1.0 share 0: %v", err)
	}
	defer handle0.Free()
	handle1, _, err := ImportKeyshare(xversionShare(t, "dkls-share-1.json"))
	if err != nil {
		t.Fatalf("import v4.1.0 share 1: %v", err)
	}
	defer handle1.Free()

	msg := []byte("xversion-cross-sign")
	hash := HashMessageForDKLs(msg)
	sig, err := RunSignInProcess([]*libtss.KeyShareHandle{handle0, handle1}, hash)
	if err != nil {
		t.Fatalf("sign with v4.1.0 shares: %v", err)
	}
	wantPub, err := hex.DecodeString(ks0.PubKey)
	if err != nil {
		t.Fatalf("decode fixture pub_key: %v", err)
	}
	valid, err := libtss.Verify(libtss.CiphersuiteSecp256k1ECDSA, msg, sig.Data, wantPub)
	if err != nil {
		t.Fatalf("verify: %v", err)
	}
	if !valid {
		t.Fatal("signature from v4.1.0 shares does not verify in current code")
	}
}
